def scan(n, K=2000):
    """2^i (x_i + 1) = 3^j (n+1) + B.  even: B += 2^i, j same.  odd: B *= 3, j += 1."""
    x=n; j=0; B=0; p2=1
    for i in range(0, K):
        if x%2==0:
            x=x//2; B = B + p2
        else:
            x=(3*x+1)//2; j+=1; B = 3*B
        p2*=2
        if 3**j < p2 and B < (p2 - 3**j)*(n+1):
            return i+1, j, x
    return None
# sanity: the identity itself
